-- name: GetInstance :one
SELECT * FROM ec2_instances WHERE partition = sqlc.arg(partition) AND account_id = sqlc.arg(account_id) AND region = sqlc.arg(region) AND resource_id = sqlc.arg(resource_id);

-- name: ListInstances :many
SELECT * FROM ec2_instances WHERE partition = sqlc.arg(partition) AND account_id = sqlc.arg(account_id) AND region = sqlc.arg(region) ORDER BY resource_id;

-- name: PreparedInstances :many
SELECT * FROM ec2_instances WHERE runtime_prepared = 1 ORDER BY partition, account_id, region, resource_id;

-- name: PendingInstances :many
SELECT * FROM ec2_instances WHERE next_action_at IS NOT NULL AND next_action_at <= sqlc.arg(deadline) ORDER BY next_action_at, partition, account_id, region, resource_id;

-- name: NextInstanceDeadline :one
SELECT next_action_at FROM ec2_instances WHERE next_action_at IS NOT NULL ORDER BY next_action_at, partition, account_id, region, resource_id LIMIT 1;

-- name: PutInstance :exec
