-- name: ListInstanceMappings :many
SELECT * FROM ec2_instance_mappings WHERE partition = sqlc.arg(partition) AND account_id = sqlc.arg(account_id) AND region = sqlc.arg(region) AND resource_id = sqlc.arg(resource_id) ORDER BY position;

-- name: InstanceVolumeAttachments :many
SELECT * FROM ec2_instance_mappings WHERE partition = sqlc.arg(partition) AND account_id = sqlc.arg(account_id) AND region = sqlc.arg(region) AND volume_id = sqlc.arg(volume_id) AND volume_id IS NOT NULL AND volume_id != '' ORDER BY resource_id, position;

-- name: DeleteInstanceMappings :exec
DELETE FROM ec2_instance_mappings WHERE partition = sqlc.arg(partition) AND account_id = sqlc.arg(account_id) AND region = sqlc.arg(region) AND resource_id = sqlc.arg(resource_id);

-- name: PutInstanceMapping :exec
INSERT INTO ec2_instance_mappings (partition, account_id, region, resource_id, position, device_name, ebs_present, associated_resource, attach_time, delete_on_termination, ebs_card_index, operator, status, volume_id, volume_owner_id)
VALUES (sqlc.arg(partition), sqlc.arg(account_id), sqlc.arg(region), sqlc.arg(resource_id), sqlc.arg(position), sqlc.arg(device_name), sqlc.arg(ebs_present), sqlc.arg(associated_resource), sqlc.arg(attach_time), sqlc.arg(delete_on_termination), sqlc.arg(ebs_card_index), sqlc.arg(operator), sqlc.arg(status), sqlc.arg(volume_id), sqlc.arg(volume_owner_id));

-- name: ListInstanceNetworks :many
SELECT * FROM ec2_instance_networks WHERE partition = sqlc.arg(partition) AND account_id = sqlc.arg(account_id) AND region = sqlc.arg(region) AND resource_id = sqlc.arg(resource_id) ORDER BY position;

-- name: DeleteInstanceNetworks :exec
DELETE FROM ec2_instance_networks WHERE partition = sqlc.arg(partition) AND account_id = sqlc.arg(account_id) AND region = sqlc.arg(region) AND resource_id = sqlc.arg(resource_id);

-- name: PutInstanceNetwork :exec
INSERT INTO ec2_instance_networks (partition, account_id, region, resource_id, position, network_interface_id) VALUES (sqlc.arg(partition), sqlc.arg(account_id), sqlc.arg(region), sqlc.arg(resource_id), sqlc.arg(position), sqlc.arg(network_interface_id));

-- name: ListInstanceGroups :many
SELECT * FROM ec2_instance_groups WHERE partition = sqlc.arg(partition) AND account_id = sqlc.arg(account_id) AND region = sqlc.arg(region) AND resource_id = sqlc.arg(resource_id) ORDER BY position;

-- name: DeleteInstanceGroups :exec
DELETE FROM ec2_instance_groups WHERE partition = sqlc.arg(partition) AND account_id = sqlc.arg(account_id) AND region = sqlc.arg(region) AND resource_id = sqlc.arg(resource_id);

-- name: PutInstanceGroup :exec
INSERT INTO ec2_instance_groups (partition, account_id, region, resource_id, position, group_id, group_name) VALUES (sqlc.arg(partition), sqlc.arg(account_id), sqlc.arg(region), sqlc.arg(resource_id), sqlc.arg(position), sqlc.arg(group_id), sqlc.arg(group_name));

-- name: ListInstanceTags :many
SELECT * FROM ec2_instance_tags WHERE partition = sqlc.arg(partition) AND account_id = sqlc.arg(account_id) AND region = sqlc.arg(region) AND resource_id = sqlc.arg(resource_id) ORDER BY position;

-- name: DeleteInstanceTags :exec
DELETE FROM ec2_instance_tags WHERE partition = sqlc.arg(partition) AND account_id = sqlc.arg(account_id) AND region = sqlc.arg(region) AND resource_id = sqlc.arg(resource_id);

-- name: PutInstanceTag :exec
INSERT INTO ec2_instance_tags (partition, account_id, region, resource_id, position, key, value) VALUES (sqlc.arg(partition), sqlc.arg(account_id), sqlc.arg(region), sqlc.arg(resource_id), sqlc.arg(position), sqlc.arg(key), sqlc.arg(value));
